/// Shortest round-trip digits and the decimal exponent: value = 0.d1d2d3... * 10^kk
fn shortest_digits(x: f64) -> (String, i32) {
    // `{:e}` gives the shortest digits that round-trip, as ryu does.
    let s = format!("{:e}", x.abs());
    let (mant, exp) = s.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let digits: String = mant.chars().filter(|c| *c != '.').collect();
    // mant = d.ddd, so value = d.ddd * 10^exp = 0.dddd * 10^(exp+1)
    (digits, exp + 1)
}

/// Formats an f64 as serde_json (ryu) does.
pub fn fmt_f64(x: f64) -> String {
    if !x.is_finite() {
        return "null".to_string();
    }
    let mut out = String::new();
    if x.is_sign_negative() {
        out.push('-');
    }
    if x == 0.0 {
        out.push_str("0.0");
        return out;
    }
    let (digits, kk) = shortest_digits(x);
    let length = digits.len() as i32;
    let k = kk - length;
    if 0 <= k && kk <= 16 {
        out.push_str(&digits);
        for _ in length..kk {
            out.push('0');
        }
        out.push_str(".0");
    } else if 0 < kk && kk <= 16 {
        out.push_str(&digits[..kk as usize]);
        out.push('.');
        out.push_str(&digits[kk as usize..]);
    } else if -5 < kk && kk <= 0 {
        out.push_str("0.");
        for _ in 0..(-kk) {
            out.push('0');
        }
        out.push_str(&digits);
    } else {
        out.push_str(&digits[..1]);
        if length > 1 {
            out.push('.');
            out.push_str(&digits[1..]);
        }
        out.push('e');
        if kk - 1 > 0 {
            out.push('+');
        }
        let _ = write!(out, "{}", kk - 1);
    }
    out
}

