fn scan_dir(dir: &Path, out: &mut Vec<String>, seen: &mut HashSet<PathBuf>, depth: usize) {
    if depth > 64 {
        return;
    }
    let Ok(rd) = std::fs::read_dir(dir) else { return };
    for e in rd.flatten() {
        let path = e.path();
        let Ok(ft) = e.file_type() else { continue };
        if ft.is_symlink() {
            let Ok(c) = std::fs::canonicalize(&path) else { continue };
            if c.is_dir() {
                if seen.insert(c.clone()) {
                    scan_dir(&c, out, seen, depth + 1);
                }
            } else if c.is_file() && is_font_file(&path) {
                read_font_file(&c, out);
            }
        } else if ft.is_file() {
            if is_font_file(&path) {
                read_font_file(&path, out);
            }
        } else if ft.is_dir() {
            scan_dir(&path, out, seen, depth + 1);
        }
    }
}

