                e.get("kind").and_then(|k| k.as_str()) == Some(kind)
                    && !names.iter().any(|n| Some(n.as_str()) == e.get("name").and_then(|x| x.as_str()))
            })
            .map(|(id, _)| *id)
            .collect();
        for id in stale {
            pr.library.remove(&id);
        }
        for n in &names {
            if pr.lib_find(kind, n).is_none() {
                pr.lib_add(kind, n);
            }
        }
    }
}

